import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import {
  NOT_RECORDED,
  headlineFiles,
  headlineOf,
  headlinePath,
  reportsIn,
} from './bench-headline.mjs';

// The figures of the documentation's performance page (operate/performance), in
// English and Chinese, generated from the benchmark reports so that the page
// never shows a number its report no longer has (D391 keeps one report of each
// kind and environment).
//
// Each report that the page quotes keeps its headline figures in
// `<report>/headline.json` beside its `.md`, written from the report's own data
// by bench-headline.mjs, each figure with the build, the CPU model and the file
// it comes from. The page holds them between two markers; docs-reference.mjs
// writes the block (`--write`) and fails when it is not what the headlines give.
// A report without a headline file is not quoted. No figure is computed across
// two reports, so none across two builds.

/** The reports the page quotes, in its order. */
export const HEADLINES = [
  'test/benchmarks/results/reports/actions-snapshot/headline.json',
  'test/benchmarks/results/reports/m5max-snapshot/headline.json',
];

export const PAGES = {
  en: 'documentation/docs/en/operate/performance.md',
  zh: 'documentation/docs/zh/operate/performance.md',
};

export const BEGIN = '<!-- performance:begin -->';
export const END = '<!-- performance:end -->';

const REPORTS =
  'https://github.com/Ahoo-Wang/Wow/blob/main/test/benchmarks/results/reports/';

const WORDS = {
  en: {
    generated:
      "<!-- Generated by .github/scripts/docs-performance.mjs from the reports' headline.json; regenerate with `pnpm docs:reference`. Do not edit. -->",
    none: 'No report quotes its figures here yet: the [reports](https://github.com/Ahoo-Wang/Wow/tree/main/test/benchmarks/results/reports) hold every measurement.',
    environments: {
      actions: 'GitHub Actions, one 4-core runner a suite',
      m5max: 'Apple M5 Max, 18 cores, 64 GB, one host',
    },
    title: (headline, environment, builds) =>
      `**${environment}**: [${headline.report}](${REPORTS}${headline.report}.md), ${builds.length === 1 ? 'build' : 'builds'} ${builds.map(b => `\`${b}\``).join(', ')}.`,
    head: '| Store | Nodes | Scenario | Keys | Peak | Sustainable | CPU, JDK, build |',
    remeasured:
      'Each figure is from the build, the JDK and the runner its row names, and each is measured again on 10.0.0-beta.3. The scenarios are those of [What was measured](#what-was-measured).',
    cluster: where =>
      `Three nodes on ${where}: the nodes, the stores and the load generator divide the same cores, so these rows show what a cluster costs (forwarding between the nodes), not what it gains. Scaling across separate machines has not been measured.`,
    where: { actions: 'one runner', m5max: 'this one host' },
    jdk: jdk =>
      jdk === NOT_RECORDED
        ? 'JDK not recorded'
        : `JDK ${jdk}${major(jdk) === 25 ? '' : ' (not JDK 25)'}`,
    nodes: n => (n === 1 ? 'one' : String(n)),
    keys: { uniform: 'uniform', zipf: 'Zipf', hot: 'one hot account' },
    clients: n => `at ${n.toLocaleString('en-US')} clients`,
    openLoop: 'open loop',
    closedLoop: 'closed loop',
    p99: ms => `p99 ${ms} ms`,
    separator: ', ',
  },
  zh: {
    generated:
      '<!-- 由 .github/scripts/docs-performance.mjs 依据各报告的 headline.json 生成；用 `pnpm docs:reference` 重新生成。请勿手改。 -->',
    none: '尚无报告在此引用其数字：全部测量见[报告](https://github.com/Ahoo-Wang/Wow/tree/main/test/benchmarks/results/reports)。',
    environments: {
      actions: 'GitHub Actions，每个套件一台 4 核 runner',
      m5max: 'Apple M5 Max，18 核，64 GB，一台主机',
    },
    title: (headline, environment, builds) =>
      `**${environment}**：[${headline.report}](${REPORTS}${headline.report}.md)，构建 ${builds.map(b => `\`${b}\``).join('、')}。`,
    head: '| 存储 | 节点 | 场景 | 键 | 峰值 | 可持续 | CPU、JDK、构建 |',
    remeasured:
      '每个数字都来自其所在行注明的构建、JDK 与机器，都将在 10.0.0-beta.3 上重测。各场景见[测了什么](#what-was-measured)。',
    cluster: where =>
      `三个节点在${where}上：节点、存储与负载生成器分用同一组 CPU 核，所以这几行显示的是集群的开销（节点之间的转发），不是它带来的收益。跨多台机器的扩展尚未测量。`,
    where: { actions: '同一台 runner', m5max: '同一台主机' },
    jdk: jdk =>
      jdk === NOT_RECORDED
        ? '未记录 JDK'
        : `JDK ${jdk}${major(jdk) === 25 ? '' : '（不是 JDK 25）'}`,
    nodes: n => (n === 1 ? '一个' : String(n)),
    keys: { uniform: '均匀', zipf: 'Zipf', hot: '单个热点账户' },
    clients: n => `${n.toLocaleString('en-US')} 个客户端`,
    openLoop: '开环',
    closedLoop: '闭环',
    p99: ms => `p99 ${ms} ms`,
    separator: '，',
  },
};

const STORES = { postgres: 'PostgreSQL', mongo: 'MongoDB' };

/** A JDK version's major version: `25.0.5+8` is 25. */
const major = jdk => Number(String(jdk).split(/[.+]/)[0]);

const rate = value =>
  `${value.toLocaleString('en-US', { maximumFractionDigits: 1 })}/s`;

/** A CPU model as a reader names it: `AMD EPYC 7763 64-Core Processor` is `EPYC 7763`. */
export const cpuName = cpu =>
  cpu
    .replace(/^AMD\s+/, '')
    .replace(/\s+\d+-Core Processor$/, '')
    .replace(/^Intel\(R\) Xeon\(R\) Platinum\s+/, 'Xeon ')
    .replace(/\s+CPU\s+@.*$/, '')
    .replace(/, 18 cores, 64 GB$/, '');

/**
 * The rows of a headline the page's table shows, each `{ store, nodes, scenario, keys, peak?, sustainable?, cpu,
 * commit }`: a single node's sustainable rates with their closed-loop saturation (Actions, `sustainable`), or the
 * sweeps' peaks and sustainable steps (M5 Max, `sweep`; not the steps measured past a sweep, nor a fixed run).
 */
export function rowsOf(headline) {
  return headline.figures.flatMap(figure => {
    if (figure.kind === 'sustainable') {
      return [
        {
          ...figure,
          peak: figure.saturation
            ? { value: figure.saturation, loop: 'closed' }
            : undefined,
          sustainable: {
            value: figure.value,
            p99Ms: figure.p99Ms,
            loop: 'open',
          },
        },
      ];
    }
    if (
      figure.kind === 'sweep' &&
      !figure.single &&
      /-sweep$/.test(figure.id)
    ) {
      return [
        {
          ...figure,
          peak: Number.isFinite(figure.value)
            ? {
                value: figure.value,
                clients: figure.clients,
                lowerBound: figure.lowerBound,
              }
            : undefined,
          sustainable: figure.sustainable ?? undefined,
        },
      ];
    }
    return [];
  });
}

/** A figure's cell: its rate, `≥` for a lower bound, where it was measured, and its p99 when it has one. */
const cell = (words, figure) =>
  figure
    ? [
        `${figure.lowerBound ? '≥ ' : ''}${rate(figure.value)}`,
        figure.clients
          ? words.clients(figure.clients)
          : figure.loop === 'closed'
            ? words.closedLoop
            : words.openLoop,
        figure.p99Ms === undefined ? '' : words.p99(figure.p99Ms),
      ]
        .filter(Boolean)
        .join(words.separator)
    : '–';

/**
 * A headline as the page reads it, refusing one that lacks what the table needs: `schema`, `report`, `environment`
 * and `figures`, each figure an `id`, a `kind`, and its `commit`, `cpu`, `jdk` and `source`, and a quoted row a known
 * store.
 */
export function checkedHeadline(headline, path) {
  const missing = ['schema', 'report', 'environment', 'figures'].filter(
    key => headline[key] === undefined,
  );
  if (missing.length > 0)
    throw new Error(`${path} lacks ${missing.join(', ')}`);
  for (const [i, figure] of headline.figures.entries()) {
    const lacks = ['id', 'kind', 'commit', 'cpu', 'jdk', 'source'].filter(
      key => figure[key] === undefined,
    );
    if (lacks.length > 0)
      throw new Error(`${path}: figure ${i + 1} lacks ${lacks.join(', ')}`);
  }
  for (const row of rowsOf(headline)) {
    if (!STORES[row.store])
      throw new Error(
        `${path}: ${row.id} lacks a known store (${Object.keys(STORES).join(', ')})`,
      );
  }
  return headline;
}

/** The block between the markers, in `locale`, from the headlines: per report, its builds and its table. */
export function performanceBlock(locale, headlines) {
  const words = WORDS[locale];
  const quoted = headlines.filter(headline => rowsOf(headline).length > 0);
  if (quoted.length === 0) return [words.generated, '', words.none].join('\n');
  const table = rows => [
    words.head,
    '| --- | ---: | --- | --- | --- | --- | --- |',
    ...rows.map(row => {
      const cells = [
        STORES[row.store],
        words.nodes(row.nodes),
        row.scenario,
        words.keys[row.keys] ?? row.keys,
        cell(words, row.peak),
        cell(words, row.sustainable),
        [cpuName(row.cpu), words.jdk(row.jdk), `\`${row.commit}\``].join(
          words.separator,
        ),
      ];
      return `| ${cells.map(text => String(text).replaceAll('|', '\\|')).join(' | ')} |`;
    }),
  ];
  const sections = quoted.map(headline => {
    const rows = rowsOf(headline);
    const builds = [...new Set(rows.map(row => row.commit))].sort();
    // A cluster's rows go in a table of their own, led by what they show: its nodes share one machine's cores.
    const single = rows.filter(row => row.nodes === 1);
    const cluster = rows.filter(row => row.nodes > 1);
    return [
      words.title(
        headline,
        words.environments[headline.environment] ?? headline.environment,
        builds,
      ),
      ...(single.length > 0 ? ['', ...table(single)] : []),
      ...(cluster.length > 0
        ? [
            '',
            words.cluster(
              words.where[headline.environment] ?? headline.environment,
            ),
            '',
            ...table(cluster),
          ]
        : []),
    ].join('\n');
  });
  return [
    words.generated,
    '',
    words.remeasured,
    '',
    sections.join('\n\n'),
  ].join('\n');
}

/** `text` with its block between the markers replaced by `block`; fails when the markers are not there once each, in order. */
export function withBlock(text, block, path) {
  const begin = text.indexOf(BEGIN);
  const end = text.indexOf(END);
  if (
    begin < 0 ||
    end < begin ||
    text.indexOf(BEGIN, begin + 1) >= 0 ||
    text.indexOf(END, end + 1) >= 0
  ) {
    throw new Error(`${path} must hold ${BEGIN} and then ${END}, once each`);
  }
  return `${text.slice(0, begin + BEGIN.length)}\n${block}\n${text.slice(end)}`;
}

/** The headlines of the reports present in `root`, as their data gives them, in the page's order. */
export function headlinesOf(root) {
  const present = new Set(reportsIn(root).map(headlinePath));
  return HEADLINES.filter(path => present.has(path)).map(path =>
    checkedHeadline(headlineOf(root, path.split('/').at(-2)), path),
  );
}

/**
 * The performance pages as the headlines give them, by path, each page's text with its block written, and each
 * report's headline.json (bench-headline.mjs): docs-reference.mjs writes and checks them together.
 */
export function performancePages(root) {
  const headlines = headlinesOf(root);
  return {
    ...headlineFiles(root),
    ...Object.fromEntries(
      Object.entries(PAGES).map(([locale, path]) => [
        path,
        withBlock(
          readFileSync(join(root, path), 'utf8'),
          performanceBlock(locale, headlines),
          path,
        ),
      ]),
    ),
  };
}
